pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ISavingsContractV2 {
    function redeem(uint256 _amount) external returns (uint256 massetReturned);
    function creditBalances(address) external view returns (uint256);
    function depositInterest(uint256 _amount) external;
    function depositSavings(uint256 _amount) external returns (uint256 creditsIssued);
    function depositSavings(uint256 _amount, address _beneficiary) external returns (uint256 creditsIssued);
    function redeemCredits(uint256 _amount) external returns (uint256 underlyingReturned);
    function redeemUnderlying(uint256 _amount) external returns (uint256 creditsBurned);
    function exchangeRate() external view returns (uint256);
    function balanceOfUnderlying(address _user) external view returns (uint256 underlying);
    function underlyingToCredits(uint256 _underlying) external view returns (uint256 credits);
    function creditsToUnderlying(uint256 _credits) external view returns (uint256 underlying);
    function underlying() external view returns (IERC20Like underlyingMasset);
}

interface IERC20Like {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint256 a1, uint256 a2, address to) public {
        a1 = bound(a1, 1, 1e24);
        a2 = bound(a2, 1, 1e24);
        vm.assume(to != address(0) && to != address(c));

        address depositor = address(0xBEEF);

        vm.startPrank(depositor);
        c.supplyTokenTo(a1, to);
        uint256 afterFirst = c.imBalances(to);
        c.supplyTokenTo(a2, to);
        vm.stopPrank();

        uint256 afterSecond = c.imBalances(to);

        // General rule: a recipient's credit balance accumulates across deposits;
        // the second deposit adds its credits to the first rather than replacing them.
        assertTrue(
            afterFirst == a1 && afterSecond == afterFirst + a2,
            "imBalances must accumulate across deposits"
        );
    }
}

