pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ISavingsContractV2 {
    function underlying() external view returns (address);
    function depositSavings(uint256 _amount) external returns (uint256 creditsIssued);
    function depositSavings(uint256 _amount, address _beneficiary) external returns (uint256 creditsIssued);
    function redeemUnderlying(uint256 _amount) external returns (uint256 creditsBurned);
    function exchangeRate() external view returns (uint256);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(ISavingsContractV2(address(new __InvMutHandleStub()))); }

    function testFuzz_property(uint96 amt1, uint96 amt2, address payer1, address payer2, address to) public {
        vm.assume(payer1 != address(0) && payer2 != address(0) && to != address(0));
        vm.assume(payer1 != payer2);
        uint256 a1 = bound(uint256(amt1), 1, 1e30);
        uint256 a2 = bound(uint256(amt2), 1, 1e30);

        vm.prank(payer1);
        c.supplyTokenTo(a1, to);
        uint256 before = c.imBalances(to);

        vm.prank(payer2);
        c.supplyTokenTo(a2, to);
        uint256 afterBal = c.imBalances(to);

        // Every successful supply strictly increases the recipient's credit balance.
        assertTrue(afterBal > before && afterBal == before + a2);
    }
}

